PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', currency TEXT NOT NULL DEFAULT 'USD', units TEXT NOT NULL DEFAULT 'metric', locale TEXT NOT NULL DEFAULT 'en', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers (id TEXT PRIMARY KEY, name TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, service_areas TEXT NOT NULL, skills TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), provider_id TEXT REFERENCES providers(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('platform_admin','customer_admin','plant_manager','maintenance','dispatcher','engineer','provider_admin','provider_engineer')), active INTEGER NOT NULL DEFAULT 1, service_areas TEXT NOT NULL DEFAULT '[]', skills TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plants (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', country TEXT NOT NULL, service_area TEXT NOT NULL, timezone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipment (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), plant_id TEXT NOT NULL REFERENCES plants(id), machine_type TEXT NOT NULL CHECK(machine_type IN ('injection','blow','extrusion','mould','auxiliary')), make TEXT NOT NULL, model TEXT NOT NULL, serial_number TEXT NOT NULL, location TEXT NOT NULL, qr_code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, UNIQUE(company_id,serial_number));
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), title TEXT NOT NULL, starts_at TEXT NOT NULL, renews_at TEXT NOT NULL, commitments TEXT NOT NULL, exclusions TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contract_equipment (contract_id TEXT NOT NULL REFERENCES contracts(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), PRIMARY KEY(contract_id,equipment_id));
CREATE TABLE IF NOT EXISTS visits (id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES contracts(id), company_id TEXT NOT NULL REFERENCES companies(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), plant_id TEXT NOT NULL REFERENCES plants(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), title TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')), symptoms TEXT NOT NULL, error_codes TEXT NOT NULL DEFAULT '', production_impact TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','assigned','accepted','in_progress','escalated','completed')), assigned_user_id TEXT REFERENCES users(id), assigned_provider_id TEXT REFERENCES providers(id), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, first_response_at TEXT, completed_at TEXT, downtime_minutes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ticket_events (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), actor_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checklist_entries (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), item TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_logs (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), user_id TEXT NOT NULL REFERENCES users(id), description TEXT NOT NULL, minutes INTEGER NOT NULL, parts_used TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS signoffs (ticket_id TEXT PRIMARY KEY REFERENCES tickets(id), customer_user_id TEXT NOT NULL REFERENCES users(id), signer_name TEXT NOT NULL, signed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parts_requests (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), ticket_id TEXT NOT NULL REFERENCES tickets(id), item TEXT NOT NULL, quantity INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'requested', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotations (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES parts_requests(id), company_id TEXT NOT NULL REFERENCES companies(id), amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, lead_days INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', approved_by TEXT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), entity_type TEXT NOT NULL CHECK(entity_type IN ('equipment','ticket','work_log')), entity_id TEXT NOT NULL, kind TEXT NOT NULL, filename TEXT NOT NULL, mime TEXT NOT NULL, size_bytes INTEGER NOT NULL, storage_name TEXT NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), company_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS device_mappings (id TEXT PRIMARY KEY, external_device_id TEXT NOT NULL UNIQUE, company_id TEXT NOT NULL REFERENCES companies(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS readings (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), external_device_id TEXT NOT NULL, observed_at TEXT NOT NULL, received_at TEXT NOT NULL, running_hours REAL, cycle_count INTEGER, temperature_c REAL, alarm_code TEXT, raw_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offline_actions (user_id TEXT NOT NULL REFERENCES users(id), client_action_id TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,client_action_id));
CREATE INDEX IF NOT EXISTS idx_tickets_company_status ON tickets(company_id,status);
CREATE INDEX IF NOT EXISTS idx_tickets_provider ON tickets(assigned_provider_id);
CREATE INDEX IF NOT EXISTS idx_readings_asset_time ON readings(equipment_id,observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_company_time ON audit_events(company_id,created_at DESC);
